[IO.File]::WriteAllText((Join-Path $PWD 'deploy.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# The deploy step: pulls the manifest at REF from the registry, checks that it hashes to the`n# digest the build pushed, then pulls each blob it names and checks each the same way.`n# Usage: sh deploy.sh REGISTRY REF DIGEST, e.g. sh deploy.sh 127.0.0.1:5000 demo/app:1.0 sha256:...`nrepo=`${2%%[:@]*}`ncurl -sS --cacert server.pem -u deploy:d3ploy -D pull.headers -o pulled.json `"oci://`$1/`$2`" || exit `$?`ngot=sha256:`$(openssl dgst -sha256 -r pulled.json | cut -d ' ' -f 1)`nsaid=`$(tr -d '\r' < pull.headers | grep -i '^docker-content-digest:' | tail -n 1 | sed 's/^[^:]*: *//')`necho `"pulled `$2: `$got`"`necho `"the registry says: `$said`"`nif [ `"`$got`" != `"`$3`" ]; then`n  echo `"not the manifest the build pushed (`$3)`"`n  exit 1`nfi`nfor blob in `$(grep -o '`"digest`":`"sha256:[0-9a-f]*`"' pulled.json | cut -d '`"' -f 4); do`n  curl -sS --cacert server.pem -u deploy:d3ploy -o blob.bin `"oci://`$1/`$repo@`$blob`" || exit `$?`n  test `"sha256:`$(openssl dgst -sha256 -r blob.bin | cut -d ' ' -f 1)`" = `"`$blob`" || { echo `"blob `$blob: hash differs`"; exit 1; }`n  echo `"blob `$(echo `"`$blob`" | cut -c 1-19): `$(wc -c < blob.bin | tr -d ' ') bytes, hash ok`"`ndone`necho `"deploy: image verified`"`n")
