$server0 = Start-Process surl -ArgumentList '--directory', 'store', '--cert', 'server.pem', '--key', 'server.key', '--user', 'build:b1ld', '--user', 'deploy:d3ploy', '--allow-uploads', 'oci://127.0.0.1:8080/' -PassThru -NoNewWindow
